import std.io

pub type AppError = Failed(String)

record Inner { seed: Int64 }

impl Inner {
    fn fetch(self) -> Result<Int64, AppError> {
        return Err(Failed("inner-bang"))
    }
}

record Outer { inner: Inner }

impl Outer {
    fn fetch(self) -> Result<Int64, AppError> {
        let v = self.inner.fetch()?
        return Ok(v + 1i64)
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let o = Outer { inner: Inner { seed: 1 } }
    let v = o.fetch()?
    io.println("v ${v}")
    return Ok(())
}
